import sys

def candies(M: int, N: int) -> int:
    return (M * N - M - N + 1) // 2

def main():
    line = sys.stdin.read().strip()
    if not line:
        return
    parts = list(map(int, line.split()))
    if len(parts) >= 2:
        M, N = parts[0], parts[1]
    else:
        return
    result = candies(M, N)
    print(result)

if __name__ == "__main__":
    main()
